            else:raise
        with open(ROOT+'/actions.jsonl','a') as f:f.write(json.dumps({'P':part.tolist(),'meta':out.meta})+'\n')
        if out.done or out.stopped:raise RuntimeError(out.meta)
    return out
class Path:
